<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/config/config.php'; require_once ROOT_PATH.'/includes/session.php'; require_once ROOT_PATH.'/includes/functions.php'; require_once ROOT_PATH.'/middleware/business.php'; require_once ROOT_PATH.'/middleware/csrf.php';
$uid=(int)currentUserId(); $message=null; $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken();$id=(int)($_POST['id']??0);try{if(($_POST['action']??'')==='start_negotiation'){$nid=(new Negotiation())->create($id,$uid);redirect(BASE_URL.'/b2b/negotiations.php?id='.$nid);} $status=(string)($_POST['status']??'');$ok=(new Quotation())->updateStatus($id,$uid,$status);$message=$ok?'RFQ status updated.':'RFQ could not be updated.';}catch(Throwable $e){error_log('B2B quotation update: '.$e->getMessage());$error='Unable to update this request.';}}
$rows=[];try{$db=Database::getInstance()->getConnection();$s=$db->prepare('SELECT q.id,q.status,q.delivery_location,q.notes,q.created_at,q.expires_at,s.supplier_name,COALESCE(GROUP_CONCAT(CONCAT(p.name," × ",qi.quantity) SEPARATOR ", "),"Custom request") AS items FROM quotation_requests q LEFT JOIN suppliers s ON s.id=q.supplier_id LEFT JOIN quotation_items qi ON qi.quotation_request_id=q.id LEFT JOIN products p ON p.id=qi.product_id WHERE q.buyer_id=? GROUP BY q.id ORDER BY q.created_at DESC');$s->execute([$uid]);$rows=$s->fetchAll();}catch(PDOException $e){error_log('B2B quotations: '.$e->getMessage());$error='Your RFQs are temporarily unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My RFQs - <?=e(SITE_NAME)?></title><link rel="stylesheet" href="<?=e(BASE_URL)?>/assets/css/style.css"></head><body class="b2b-page"><header class="directory-header"><div class="container directory-header-row"><a class="brand" href="<?=e(BASE_URL)?>/b2b/"><span class="brand-mark">Q</span><span><strong>QUINCY</strong><small>BUSINESS</small></span></a><nav><a href="<?=e(BASE_URL)?>/b2b/marketplace.php">Marketplace</a><a href="<?=e(BASE_URL)?>/b2b/suppliers.php">Suppliers</a><a class="directory-active" href="<?=e(BASE_URL)?>/b2b/quotations.php">My RFQs</a><a href="<?=e(BASE_URL)?>/b2b/negotiations.php">Negotiations</a></nav></div></header><main class="container b2b-main"><div class="directory-breadcrumb"><a href="<?=e(BASE_URL)?>/b2b/">Workspace</a><span>/</span>My quotation requests</div><section class="rfq-heading"><p class="eyebrow">SOURCE MANAGEMENT</p><h1>Keep every RFQ moving.</h1><p>Review responses, update request status, and open a negotiation when terms need discussion.</p></section><?php if($message):?><div class="catalog-notice"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="catalog-notice"><?=e($error)?></div><?php elseif(!$rows):?><div class="supplier-empty"><h2>No RFQs yet</h2><p>Browse products and request a quotation from a supplier.</p><a href="<?=e(BASE_URL)?>/b2b/marketplace.php">Browse marketplace</a></div><?php else:?><div class="b2b-table"><?php foreach($rows as $r):?><article class="b2b-table-row"><div><strong><?=e($r['items'])?></strong><small><?=e($r['supplier_name']?:'Supplier matching')?> · <?=e($r['delivery_location'])?> · <?=e(date('M j, Y',strtotime((string)$r['created_at'])))?></small></div><span class="status-badge status-<?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span><div class="b2b-card-actions"><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?= (int)$r['id']?>"><input type="hidden" name="action" value="start_negotiation"><button class="outline-button" type="submit">Start negotiation</button></form><?php if(in_array($r['status'],['pending','quoted','negotiating'],true)):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?= (int)$r['id']?>"><input type="hidden" name="status" value="cancelled"><button class="outline-button" type="submit">Cancel</button></form><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></main></body></html>